// Improved Express application with comprehensive security practices
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const hpp = require('hpp');
const compression = require('compression');

require('dotenv').config();

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
}));

app.use(cors({
  origin: process.env.NODE_ENV === 'production' ? process.env.FRONTEND_URL : '*',
  credentials: true,
}));

app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Data sanitization against NoSQL query injection
app.use(mongoSanitize());

// Data sanitization against XSS
app.use(xss());

// Prevent parameter pollution
app.use(hpp());

// Compression
app.use(compression());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Custom error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't leak error details in production
  const errorResponse = process.env.NODE_ENV === 'production' 
    ? { error: 'Something went wrong' }
    : { error: err.message, stack: err.stack };

  res.status(err.status || 500).json(errorResponse);
});

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);
  next();
});

// Utility function for input validation
const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

const validateInput = (input, type = 'string') => {
  if (typeof input !== 'string') return false;

  // Basic sanitization
  const sanitized = input.trim();

  if (type === 'email') {
    return validateEmail(sanitized);
  }

  if (type === 'number') {
    return !isNaN(sanitized) && isFinite(sanitized);
  }

  // Default: basic string validation
  return sanitized.length > 0 && sanitized.length <= 255;
};

// Health endpoint with improved error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Health check failed' });
  }
});

// Users endpoint with input validation and error handling
app.get('/users', (req, res) => {
  try {
    // Validate query parameters if any
    const { limit, offset } = req.query;

    if (limit && !validateInput(limit, 'number')) {
      return res.status(400).json({ error: 'Invalid limit parameter' });
    }

    if (offset && !validateInput(offset, 'number')) {
      return res.status(400).json({ error: 'Invalid offset parameter' });
    }

    // Simulated user data (in real app, this would come from database)
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        createdAt: new Date().toISOString()
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        createdAt: new Date().toISOString()
      },
    ];

    // Apply pagination if parameters provided
    const result = {
      users: users,
      total: users.length,
      limit: limit ? parseInt(limit) : null,
      offset: offset ? parseInt(offset) : null
    };

    res.json(result);

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ error: 'Failed to retrieve users' });
  }
});

// New endpoint with parameter validation
app.get('/users/:id', (req, res) => {
  try {
    const { id } = req.params;

    // Validate ID parameter
    if (!validateInput(id, 'number')) {
      return res.status(400).json({ error: 'Invalid user ID' });
    }

    const userId = parseInt(id);

    // In real application, this would query a database
    const user = { id: userId, name: 'Test User', email: 'test@example.com' };

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);

  } catch (error) {
    console.error('User detail endpoint error:', error);
    res.status(500).json({ error: 'Failed to retrieve user' });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  process.exit(0);
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

