    if (response.headers[header]) {
      console.log(`✓ ${header}: ${response.headers[header]}`);
    } else {
      console.log(`✗ ${header}: Missing`);
    }
  });
}

// Test input validation
async function testInputValidation() {
  console.log('\nTesting Input Validation...');

  // Test invalid parameters
  const response = await request(app)
    .get('/users')
    .query({ page: 'invalid', limit: '999' });

  if (response.status === 400 && response.body.error) {
    console.log('✓ Input validation working correctly');
    console.log('  Error details:', response.body.details);
  } else {
    console.log('✗ Input validation failed');
  }
}

// Test rate limiting (basic check)
async function testRateLimiting() {
  console.log('\nTesting Rate Limiting Setup...');

  // Make multiple requests quickly
  const requests = [];
  for (let i = 0; i < 5; i++) {
    requests.push(request(app).get('/health'));
  }

  const responses = await Promise.all(requests);

  // Check if rate limiting headers are present
  const rateLimitHeaders = [
    'ratelimit-limit',
    'ratelimit-remaining',
    'ratelimit-reset'
  ];

  rateLimitHeaders.forEach(header => {
    if (responses[0].headers[header.toLowerCase()]) {
      console.log(`✓ ${header}: ${responses[0].headers[header.toLowerCase()]}`);
    } else {
      console.log(`✗ ${header}: Not detected`);
    }
  });
}

// Run all tests
async function runSecurityTests() {
  try {
    console.log('Running Security Tests...\n');

    await testSecurityHeaders();
    await testInputValidation();
    await testRateLimiting();

    console.log('\nSecurity tests completed!');

  } catch (error) {
    console.error('Test error:', error);
  }
}

// Run tests if this file is executed directly
if (require.main === module) {
  runSecurityTests();
}

module.exports = { runSecurityTests };

