// Enhanced application with security best practices
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// 1. Security Headers
app.use(helmet());

// 2. CORS Configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  credentials: true
}));

// 3. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// 4. Body Parsing with Limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Input Validation Middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

// 6. Global Error Handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Don't leak error details in production
  const response = process.env.NODE_ENV === 'production' 
    ? { error: 'Internal server error' }
    : { error: error.message, stack: error.stack };

  res.status(error.status || 500).json(response);
});

// 7. Routes with Input Validation
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: process.env.NODE_ENV || 'development'
  });
});

app.get('/users', [
  // Input validation
  body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
  body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100')
], validateRequest, (req, res) => {
  try {
    const { page = 1, limit = 10 } = req.query;

    // Mock data - in real application, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: new Date().toISOString() },
      { id: 2, name: 'Bob', email: 'bob@example.com', createdAt: new Date().toISOString() },
    ];

    res.json({
      users,
      pagination: {
        page: parseInt(page),
        limit: parseInt(limit),
        total: users.length
      }
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Failed to fetch users' });
  }
});

// 8. Request Logging Middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// 9. 404 Handler
app.use('*', (req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

// 10. Graceful Shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  process.exit(0);
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

// Simple security test script
const request = require('supertest');
const app = require('./app-enhanced');

// Test security headers
async function testSecurityHeaders() {
  console.log('Testing security headers...');

  const response = await request(app).get('/health');

  // Check important security headers
  const securityHeaders = {
    'X-Content-Type-Options': 'nosniff',
    'X-Frame-Options': 'DENY',
    'X-XSS-Protection': '1; mode=block',
    'Strict-Transport-Security': 'max-age=31536000; includeSubDomains'
  };

  Object.entries(securityHeaders).forEach(([header, expectedValue]) => {
    if (response.headers[header.toLowerCase()] === expectedValue) {
      console.log(`✅ ${header}: ${expectedValue}`);
    } else {
      console.log(`❌ ${header}: Expected ${expectedValue}, got ${response.headers[header.toLowerCase()]}`);
    }
  });
}

// Test rate limiting
async function testRateLimiting() {
  console.log('\nTesting rate limiting...');

  // Make multiple requests quickly
  const requests = Array(5).fill().map(() => 
    request(app).get('/health')
  );

  const responses = await Promise.all(requests);

  // Should all succeed (within rate limit)
  const successCount = responses.filter(res => res.status === 200).length;
  console.log(`✅ ${successCount}/5 requests succeeded (within rate limit)`);
}

// Test input validation
async function testInputValidation() {
  console.log('\nTesting input validation...');

  // Test invalid input
  const response = await request(app)
    .get('/users')
    .query({ page: 'invalid', limit: 200 });

  if (response.status === 400) {
    console.log('✅ Input validation working - rejected invalid parameters');
    console.log('Validation errors:', response.body.details);
  } else {
    console.log('❌ Input validation failed');
  }
}

// Test 404 handling
async function test404Handling() {
  console.log('\nTesting 404 handling...');

  const response = await request(app).get('/nonexistent-route');

  if (response.status === 404) {
    console.log('✅ 404 handling working correctly');
  } else {
    console.log('❌ 404 handling failed');
  }
}

// Run all tests
async function runTests() {
  try {
    await testSecurityHeaders();
    await testRateLimiting();
    await testInputValidation();
    await test404Handling();

    console.log('\n🎉 Security tests completed!');
    process.exit(0);
  } catch (error) {
    console.error('Test error:', error);
    process.exit(1);
  }
}

// Start tests if run directly
if (require.main === module) {
  runTests();
}

module.exports = { testSecurityHeaders, testRateLimiting, testInputValidation, test404Handling };

