  // Basic security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Simple request logging
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);

  next();
});

// Input validation middleware
const validateQueryParams = (req, res, next) => {
  // Simple validation for any query parameters
  const queryParams = req.query;

  // Example: Validate that numeric parameters are actually numbers
  if (queryParams.limit && isNaN(parseInt(queryParams.limit))) {
    return res.status(400).json({ 
      error: 'Invalid parameter', 
      message: 'Limit must be a valid number' 
    });
  }

  if (queryParams.page && isNaN(parseInt(queryParams.page))) {
    return res.status(400).json({ 
      error: 'Invalid parameter', 
      message: 'Page must be a valid number' 
    });
  }

  next();
};

