# Security Improvements for app.js

## Current State Analysis
The current app.js is a basic Express application with minimal error handling and security features.

## Critical Security Improvements Needed

### 1. Input Validation & Sanitization

```javascript
// Add input validation middleware
const { body, validationResult } = require('express-validator');

// Validation for user endpoints
const validateUserInput = [
  body('name').isLength({ min: 1, max: 100 }).trim().escape(),
  body('email').isEmail().normalizeEmail(),
  body('id').isInt({ min: 1 })
];
```

### 2. Enhanced Error Handling

```javascript
// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak stack traces in production
  if (process.env.NODE_ENV === 'production') {
    return res.status(500).json({ 
      error: 'Internal Server Error',
      message: 'Something went wrong' 
    });
  }

  res.status(500).json({ 
    error: err.message, 
    stack: err.stack 
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});
```

### 3. Security Headers

```javascript
// Add security middleware
const helmet = require('helmet');
app.use(helmet());

// CORS configuration
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS || 'http://localhost:3000',
  credentials: true
}));
```

### 4. Rate Limiting

```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});

app.use(limiter);
```

### 5. Environment-Specific Configuration

```javascript
// Load environment variables
require('dotenv').config();

// Security: Don't expose server details
app.disable('x-powered-by');

// Environment-specific configurations
if (process.env.NODE_ENV === 'production') {
  // Production-specific security settings
  app.set('trust proxy', 1);
}
```

### 6. Enhanced Users Endpoint with Security

```javascript
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters if any
    const { limit, offset } = req.query;

    if (limit && !/^\d+$/.test(limit)) {
      return res.status(400).json({ error: 'Invalid limit parameter' });
    }

    // Mock data with proper sanitization
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply limit/offset if provided
    let result = users;
    if (limit) {
      const numLimit = parseInt(limit, 10);
      result = users.slice(0, numLimit);
    }

    res.json(result);
  } catch (error) {
    next(error);
  }
});
```

### 7. Input Validation Middleware

```javascript
// Validation middleware
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      errors: errors.array(),
      message: 'Validation failed' 
    });
  }
  next();
};
```

### 8. Logging and Monitoring

```javascript
// Add request logging
const morgan = require('morgan');

// Don't log sensitive information
app.use(morgan('combined', {
  skip: (req, res) => {
    // Skip logging health checks or sensitive endpoints
    return req.path === '/health' || req.path.includes('admin');
  }
}));
```

## Required Dependencies

Add these to package.json:
```json
{
  "dependencies": {
    "express": "^4.18.2",
    "helmet": "^7.1.0",
    "cors": "^2.8.5",
    "express-rate-limit": "^7.1.5",
    "express-validator": "^7.0.1",
    "dotenv": "^16.3.1",
    "morgan": "^1.10.0"
  }
}
```

## Environment Variables

Create a proper .env file (not .env.test for production):
```
NODE_ENV=production
PORT=3000
ALLOWED_ORIGINS=http://localhost:3000,https://yourdomain.com
```

## Security Checklist

- [ ] Input validation on all endpoints
- [ ] SQL injection prevention (if using databases)
- [ ] XSS protection
- [ ] CSRF protection
- [ ] Rate limiting
- [ ] Security headers
- [ ] Proper error handling
- [ ] Environment variable security
- [ ] Request logging
- [ ] Authentication/authorization (if needed)
- [ ] Regular dependency updates

## Next Steps

1. Install the required security packages
2. Implement the suggested middleware
3. Set up proper environment configuration
4. Add authentication if the API needs to be protected
5. Regular security audits and dependency updates

// Enhanced application with security best practices
// Improved error handling and input validation

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, validationResult } = require('express-validator');
require('dotenv').config();

const app = express();

// Security middleware
app.use(helmet());
app.disable('x-powered-by');

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : 'http://localhost:3000',
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Request logging - skip sensitive endpoints
app.use(morgan('combined', {
  skip: (req, res) => req.path === '/health'
}));

// Body parsing middleware
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      errors: errors.array(),
      message: 'Validation failed' 
    });
  }
  next();
};

// Health endpoint with improved error handling
app.get('/health', (req, res, next) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error);
  }
});

// Users endpoint with input validation and security
app.get('/users', [
  // Validate query parameters
  body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer')
], validate, (req, res, next) => {
  try {
    const { limit, offset } = req.query;

    // Mock user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply filtering with security in mind
    let result = users;

    if (limit) {
      const numLimit = parseInt(limit, 10);
      result = users.slice(0, numLimit);
    }

    // Sanitize output - remove sensitive data if needed
    const sanitizedUsers = result.map(user => ({
      id: user.id,
      name: user.name,
      email: user.email
      // Don't include sensitive fields like passwords
    }));

    res.json(sanitizedUsers);
  } catch (error) {
    next(error);
  }
});

// 404 handler for unknown routes
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} not found`
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Don't expose stack traces in production
  const errorResponse = {
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'production' 
      ? 'Something went wrong. Please try again later.' 
      : err.message
  };

  if (process.env.NODE_ENV !== 'production') {
    errorResponse.stack = err.stack;
  }

  res.status(err.status || 500).json(errorResponse);
});

// Graceful shutdown handling
process.on('SIGINT', () => {
  console.log('Received SIGINT. Shutting down gracefully...');
  process.exit(0);
});

process.on('SIGTERM', () => {
  console.log('Received SIGTERM. Shutting down gracefully...');
  process.exit(0);
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

