    if (id && !/^\d+$/.test(id)) {
      validationErrors.push('ID must be a numeric value');
    }

    if (!/^\d+$/.test(limit) || parseInt(limit) > 100) {
      validationErrors.push('Limit must be a number and cannot exceed 100');
    }

    if (!/^\d+$/.test(offset)) {
      validationErrors.push('Offset must be a numeric value');
    }

    if (validationErrors.length > 0) {
      return res.status(400).json({ 
        error: 'Validation failed', 
        details: validationErrors 
      });
